// Homescreen activated-item swipe button: tap deactivates, long-press schedules.
function ActivatedSwipeButton({ id, onTap, onLongPress }) {
  const ref = useRef(null)
  const press = useActivatePress({
    onTap: () => onTap(id),
    onLongPress: () => onLongPress(id, ref.current),
  })
  return (
    <button ref={ref} className="swipe-action-btn active-tag activated" {...press}>
      <div className="swipe-active-inner"><RemoveSvg/></div>
    </button>
  )
}

// Open a (possibly scheme-less) URL in a new browser tab
function openUrl(url) {
  if (!url) return
  let u = url.trim()
  // A phone number in the link field → start a call instead of opening a URL
  const digits = u.replace(/\D/g, '')
  if (/^[+()\-.\s\d]+$/.test(u) && digits.length >= 7 && digits.length <= 15) {
    window.location.href = 'tel:' + u.replace(/[^\d+]/g, '')
    return
  }
  if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(u)) u = 'https://' + u
  window.open(u, '_blank', 'noopener,noreferrer')
}

// Strip the scheme for a cleaner one-line preview
function displayUrl(url) {
  if (!url) return ''
  const t = url.trim()
  const d = t.replace(/\D/g, '')
  // Recognised phone number → format with parentheses + dash
  if (/^[+()\-.\s\d]+$/.test(t) && d.length >= 7 && d.length <= 15) {
    if (d.length === 10) return `(${d.slice(0, 3)}) ${d.slice(3, 6)}-${d.slice(6)}`
    if (d.length === 11 && d[0] === '1') return `1 (${d.slice(1, 4)}) ${d.slice(4, 7)}-${d.slice(7)}`
    if (d.length === 7) return `${d.slice(0, 3)}-${d.slice(3)}`
    return t
  }
  return url.replace(/^[a-z][a-z0-9+.-]*:\/\//i, '').replace(/\/$/, '')
}

function closeSwipeRow(row) {
  if (!row) return
  row.classList.remove('swiped-left', 'swiped-right')
  const content = row.querySelector('.swipe-content')
  if (content) { content.style.transition = ''; content.style.transform = '' }
}

function useSwipe() {
  const swipeState = useRef({})
  const onPointerDown = useCallback((e, id) => {
    if (e.target.closest('.swipe-action-btn') || e.target.closest('.checkbox-wrap')) return
    const row = e.currentTarget.closest('.swipe-row')
    if (!row) return
    swipeState.current = { id, startX: e.clientX, startY: e.clientY, row, dir: null }
    const onMove = (e2) => {
      const s = swipeState.current
      if (!s.row) return
      const dx = e2.clientX - s.startX, dy = e2.clientY - s.startY
      if (!s.dir) {
        if (Math.abs(dy) > 8) { cleanup(); return }
        if (Math.abs(dx) > 10) s.dir = dx < 0 ? 'left' : 'right'
        else return
      }
      const content = s.row.querySelector('.swipe-content')
      if (!content) return
      const base = s.row.classList.contains('swiped-left') ? -84 : s.row.classList.contains('swiped-right') ? 84 : 0
      content.style.transition = 'none'
      content.style.transform = `translateX(${Math.max(-84, Math.min(84, base + dx))}px)`
    }
    const onUp = (e2) => {
      const s = swipeState.current
      if (!s.row) { cleanup(); return }
      const dx = e2.clientX - s.startX
      const content = s.row.querySelector('.swipe-content')
      if (!content) { cleanup(); return }
      content.style.transition = ''
      const total = (s.row.classList.contains('swiped-left') ? -84 : s.row.classList.contains('swiped-right') ? 84 : 0) + dx
      if (total < -36) { s.row.classList.add('swiped-left'); s.row.classList.remove('swiped-right'); content.style.transform = '' }
      else if (total > 36) { s.row.classList.add('swiped-right'); s.row.classList.remove('swiped-left'); content.style.transform = '' }
      else { s.row.classList.remove('swiped-left', 'swiped-right'); content.style.transform = '' }
      cleanup()
    }
    const handleCancel = () => {
      const s2 = swipeState.current
      if (s2.row && s2.dir) {
        const c2 = s2.row.querySelector('.swipe-content')
        if (c2) {
          c2.style.transition = ''
          const m = c2.style.transform.match(/translateX\((-?[\d.]+)px\)/)
          const cx = m ? parseFloat(m[1]) : 0
          if (cx < -36) { s2.row.classList.add('swiped-left'); s2.row.classList.remove('swiped-right') }
          else if (cx > 36) { s2.row.classList.add('swiped-right'); s2.row.classList.remove('swiped-left') }
          else { s2.row.classList.remove('swiped-left', 'swiped-right') }
          c2.style.transform = ''
        }
      }
      document.removeEventListener('pointermove', onMove)
      document.removeEventListener('pointerup', onUp)
      document.removeEventListener('pointercancel', handleCancel)
    }
    const cleanup = () => {
      document.removeEventListener('pointermove', onMove)
      document.removeEventListener('pointerup', onUp)
      document.removeEventListener('pointercancel', handleCancel)
    }
    document.addEventListener('pointermove', onMove)
    document.addEventListener('pointerup', onUp)
    document.addEventListener('pointercancel', handleCancel)
  }, [])
  return { onPointerDown }
}

function useDragReorder(containerRef, items, onReorder, uncheckedCountProp) {
  const dragRef = useRef(null)
  const flipRef = useRef(null)
  const itemsRef = useRef(items)
  itemsRef.current = items
  const ucRef = useRef(uncheckedCountProp)
  ucRef.current = uncheckedCountProp

  useLayoutEffect(() => {
    const flip = flipRef.current
    if (!flip) return
    flipRef.current = null
    flip.forEach(({ el }) => { el.style.transition = 'none'; el.style.transform = ''; el.style.opacity = '' })
    document.body.offsetHeight
    const frames = flip.map(({ el, fromTop }) => ({ el, dy: fromTop - el.getBoundingClientRect().top })).filter(f => Math.abs(f.dy) > 1)
    if (!frames.length) return
    frames.forEach(({ el, dy }) => { el.style.transition = 'none'; el.style.transform = `translateY(${dy}px)` })
    document.body.offsetHeight
    requestAnimationFrame(() => {
      frames.forEach(({ el }) => { el.style.transition = 'transform 250ms ease'; el.style.transform = '' })
      setTimeout(() => frames.forEach(({ el }) => { el.style.transition = '' }), 250)
    })
  }, [items])

  const onDragPointerDown = useCallback((e, id) => {
    if (e.target.closest('.swipe-action-btn') || e.target.closest('.checkbox-wrap')) return
    const startX = e.clientX, startY = e.clientY
    let started = false, longPressTimer = null
    const preventScroll = (e) => { if (started) e.preventDefault() }
    const start = (clientY) => {
      const container = containerRef.current
      if (!container) return false
      const snapshots = [...container.children].map(w => {
        const sr = w.querySelector('.swipe-row[data-swipe-id]')
        return sr ? { el: sr, wrapper: w, id: +sr.dataset.swipeId, rect: sr.getBoundingClientRect() } : null
      }).filter(Boolean)
      const dragIdx = snapshots.findIndex(s => s.id === id)
      if (dragIdx < 0) return false
      const uc = ucRef.current
      const uncheckedCount = uc !== undefined ? uc : snapshots.length
      if (uc !== undefined && dragIdx >= uncheckedCount) return false
      const dragged = snapshots[dragIdx]
      const appEl = document.getElementById('app'), portal = document.getElementById('animation-portal')
      if (!appEl || !portal) return false
      const appRect = appEl.getBoundingClientRect()
      const cloneTop = dragged.rect.top - appRect.top - 4
      let topBound = -Infinity, bottomBound = Infinity
      if (uc !== undefined && uncheckedCount > 0) {
        topBound = snapshots[0].rect.top - appRect.top - 4
        const lastUnchecked = snapshots[uncheckedCount - 1]
        bottomBound = (lastUnchecked.rect.top + lastUnchecked.rect.height) - appRect.top - dragged.wrapper.getBoundingClientRect().height - 4
      }
      const cloneInner = dragged.el.cloneNode(true)
      cloneInner.style.cssText = 'pointer-events:none;background:#F7F6F3;'
      const clone = document.createElement('div')
      clone.style.cssText = ['position:absolute', `left:${dragged.rect.left - appRect.left - 4}px`, `top:${cloneTop}px`, `width:${dragged.rect.width + 8}px`, 'padding:4px 0', 'pointer-events:none', 'box-shadow:0 4px 20px rgba(0,0,0,0.10)', 'border-radius:8px', 'border:1px solid #C2C1BF', 'background:#F7F6F3', 'overflow:hidden', 'z-index:999'].join(';')
      clone.appendChild(cloneInner)
      portal.appendChild(clone)
      dragged.wrapper.style.opacity = '0'
      dragRef.current = { clone, snapshots, dragIdx, currentIdx: dragIdx, cloneTop, startY: clientY, draggedH: dragged.wrapper.getBoundingClientRect().height, uncheckedCount, topBound, bottomBound }
      return true
    }
    const doStart = (clientY, longPress) => {
      if (started) return
      started = start(clientY)
      if (!started) return
      if (longPress) {
        const s = dragRef.current
        if (s) { s.clone.style.transition = 'box-shadow 120ms ease'; s.clone.style.boxShadow = '0 8px 24px rgba(0,0,0,0.18)'; setTimeout(() => { if (dragRef.current === s) s.clone.style.transition = '' }, 120) }
      }
    }
    longPressTimer = setTimeout(() => { longPressTimer = null; doStart(startY, true) }, 250)
    document.addEventListener('touchmove', preventScroll, { passive: false })
    const applyShifts = (snapshots, dragIdx, newIdx, draggedH, uncheckedCount) => {
      snapshots.forEach((snap, i) => {
        if (i === dragIdx) return
        if (i >= uncheckedCount) return
        let dy = 0
        if (newIdx < dragIdx && i >= newIdx && i < dragIdx) dy = draggedH
        if (newIdx > dragIdx && i > dragIdx && i <= newIdx) dy = -draggedH
        snap.wrapper.style.transition = 'transform 180ms ease'
        snap.wrapper.style.transform = dy ? `translateY(${dy}px)` : ''
      })
    }
    const onMove = (e2) => {
      const dx = Math.abs(e2.clientX - startX), dy = Math.abs(e2.clientY - startY)
      if (longPressTimer && (dx > 8 || dy > 8)) { clearTimeout(longPressTimer); longPressTimer = null; document.removeEventListener('touchmove', preventScroll) }
      if (!started) return
      e2.preventDefault()
      const s = dragRef.current
      if (!s) return
      const rawTop = s.cloneTop + (e2.clientY - s.startY)
      s.clone.style.top = (s.topBound > -Infinity ? Math.max(s.topBound, Math.min(s.bottomBound, rawTop)) : rawTop) + 'px'
      const targetSnaps = s.snapshots.slice(0, s.uncheckedCount)
      const nonDragged = targetSnaps.filter((_, i) => i !== s.dragIdx)
      let insertAt = nonDragged.length
      for (let j = 0; j < nonDragged.length; j++) { if (e2.clientY < nonDragged[j].rect.top + nonDragged[j].rect.height / 2) { insertAt = j; break } }
      const newIdx = Math.min(insertAt, s.uncheckedCount - 1)
      if (newIdx !== s.currentIdx) { s.currentIdx = newIdx; applyShifts(s.snapshots, s.dragIdx, s.currentIdx, s.draggedH, s.uncheckedCount) }
    }
    const onCancel = () => {
      clearTimeout(longPressTimer); longPressTimer = null
      document.removeEventListener('pointermove', onMove, { passive: false })
      document.removeEventListener('pointerup', onUp)
      document.removeEventListener('pointercancel', onCancel)
      document.removeEventListener('touchmove', preventScroll)
      const s = dragRef.current
      if (!s) return
      dragRef.current = null
      s.clone.remove()
      s.snapshots.forEach(snap => { snap.wrapper.style.transition = ''; snap.wrapper.style.transform = ''; snap.wrapper.style.opacity = '' })
    }
    const onUp = () => {
      clearTimeout(longPressTimer); longPressTimer = null
      document.removeEventListener('pointermove', onMove, { passive: false })
      document.removeEventListener('pointerup', onUp)
      document.removeEventListener('pointercancel', onCancel)
      document.removeEventListener('touchmove', preventScroll)
      const s = dragRef.current
      if (!s || !started) return
      dragRef.current = null
      if (s.currentIdx === s.dragIdx) { s.clone.remove(); s.snapshots.forEach(snap => { snap.wrapper.style.transition = ''; snap.wrapper.style.transform = ''; snap.wrapper.style.opacity = '' }); return }
      const cloneReleaseTop = s.clone.getBoundingClientRect().top
      const fromTops = s.snapshots.map((snap, i) => i === s.dragIdx ? cloneReleaseTop : snap.wrapper.getBoundingClientRect().top)
      s.clone.remove()
      const visibleIds = s.snapshots.map(sn => sn.id)
      const [movedId] = visibleIds.splice(s.dragIdx, 1)
      visibleIds.splice(s.currentIdx, 0, movedId)
      const allItems = itemsRef.current
      const visibleSet = new Set(s.snapshots.map(sn => sn.id))
      const hidden = allItems.filter(it => !visibleSet.has(it.id))
      const newOrder = [...visibleIds.map(sid => allItems.find(it => it.id === sid)).filter(Boolean), ...hidden]
      flipRef.current = s.snapshots.map((snap, i) => ({ el: snap.wrapper, fromTop: fromTops[i] }))
      onReorder(newOrder)
    }
    document.addEventListener('pointermove', onMove, { passive: false })
    document.addEventListener('pointerup', onUp)
    document.addEventListener('pointercancel', onCancel)
  }, [containerRef, onReorder])

  return { onDragPointerDown }
}

// Activated todos — aggregated from all projects into one "Lists" card
function ActivatedTodosCard({ items, onToggle, onDelete, onDeactivate }) {
  const { reorderHomeTodos, categories, setProjectTodoScheduled, openDetail, setOpenDetail } = useAppContext()
  const categoriesRef = useRef(categories)
  categoriesRef.current = categories
  const [calFor, setCalFor] = useState(null)
  const openSchedule = useCallback((id, el) => {
    const item = items.find(t => t.id === id)
    if (!item) return
    closeSwipeRow(el?.closest('.swipe-row'))
    const idx = categories.findIndex(c => c.id === item.categoryId)
    setCalFor({ id, categoryId: item.categoryId, projectId: item.projectId, current: item.scheduledDate || null, anchorRect: toAnchorRect(el), accent: idx >= 0 ? getCategoryAccent(idx) : null })
  }, [items, categories])
  const [hideCompleted, setHideCompleted] = useState(() => {
    try { return localStorage.getItem('hc-activated-todos') !== 'false' } catch { return true }
  })
  const openTodoId = openDetail?.type === 'todo' ? openDetail.id : null
  const setOpenTodoId = (id) => setOpenDetail(id == null ? null : (prev => (prev?.type === 'todo' && prev.id === id) ? null : { type: 'todo', id }))
  const todoTapState = useRef({})
  const cardRef = useRef(null)
  const containerRef = useRef(null)
  const checkTimers = useRef({})
  const checkPopping = useRef({})
  const toggleFlipRef = useRef(null)
  const showingRef = useRef(false)
  const [menuOpen, setMenuOpen] = useState(false)
  const menuRef = useRef(null)

  const hasChecked = items.some(t => t.checked)
  const sorted = hideCompleted
    ? items.filter(t => !t.checked)
    : [...items.filter(t => !t.checked), ...items.filter(t => t.checked)]
  const uncheckedCount = hideCompleted ? undefined : items.filter(t => !t.checked).length

  const handleDelete = useCallback((id) => {
    const item = items.find(t => t.id === id)
    if (!item) return
    const swipeRow = containerRef.current?.querySelector(`[data-swipe-id="${id}"]`)
    const wrapper = swipeRow?.parentElement
    if (!wrapper) { onDelete(item.categoryId, item.projectId, id); return }
    wrapper.animate([{ background: 'rgba(178,74,74,0)' }, { background: 'rgba(178,74,74,0.20)', offset: 0.4 }, { background: 'rgba(178,74,74,0)' }], { duration: 280, fill: 'none' })
    setTimeout(() => {
      const height = wrapper.getBoundingClientRect().height
      wrapper.style.height = height + 'px'; wrapper.style.overflow = 'hidden'
      requestAnimationFrame(() => requestAnimationFrame(() => { wrapper.style.transition = 'height 220ms ease, opacity 180ms ease'; wrapper.style.height = '0'; wrapper.style.opacity = '0' }))
      setTimeout(() => onDelete(item.categoryId, item.projectId, id), 250)
    }, 180)
  }, [onDelete, items])

  const handleDeactivate = useCallback((id) => {
    const item = items.find(t => t.id === id)
    if (!item) return
    const swipeRow = containerRef.current?.querySelector(`[data-swipe-id="${id}"]`)
    const wrapper = swipeRow?.parentElement
    if (!wrapper) { onDeactivate(item.categoryId, item.projectId, id); return }
    const catIdx = categories.findIndex(c => c.id === item.categoryId)
    const a = catIdx >= 0 ? getCategoryAccent(catIdx) : ACCENT_COLORS[0]
    // First close the row (snap back to center)
    closeSwipeRow(swipeRow)
    setTimeout(() => {
      // Then flash and collapse
      wrapper.animate([{ background: `rgba(${a.baseRgb},0)` }, { background: `rgba(${a.baseRgb},0.25)`, offset: 0.4 }, { background: `rgba(${a.baseRgb},0)` }], { duration: 280, fill: 'none' })
      setTimeout(() => {
        const height = wrapper.getBoundingClientRect().height
        wrapper.style.height = height + 'px'; wrapper.style.overflow = 'hidden'
        requestAnimationFrame(() => requestAnimationFrame(() => { wrapper.style.transition = 'height 220ms ease, opacity 180ms ease'; wrapper.style.height = '0'; wrapper.style.opacity = '0' }))
        setTimeout(() => onDeactivate(item.categoryId, item.projectId, id), 250)
      }, 180)
    }, 200)
  }, [onDeactivate, items, categories])

  const handleReorder = useCallback((newOrder) => {
    // Single cross-project order for the home Lists card.
    reorderHomeTodos(newOrder)
  }, [reorderHomeTodos])

  const { onPointerDown } = useSwipe()
  const { onDragPointerDown } = useDragReorder(containerRef, sorted, handleReorder, uncheckedCount)

  useEffect(() => {
    const card = cardRef.current
    if (!card) return
    requestAnimationFrame(() => card.classList.add('visible'))
  }, [])

  // FLIP-animate rows after checkbox toggle reorders the list
  useLayoutEffect(() => {
    const flip = toggleFlipRef.current
    if (!flip) return
    toggleFlipRef.current = null
    document.body.offsetHeight
    const frames = flip.map(({ el, top }) => ({ el, dy: top - el.getBoundingClientRect().top })).filter(f => Math.abs(f.dy) > 1)
    if (!frames.length) return
    frames.forEach(({ el, dy }) => { el.style.transition = 'none'; el.style.transform = `translateY(${dy}px)` })
    document.body.offsetHeight
    requestAnimationFrame(() => {
      frames.forEach(({ el }) => { el.style.transition = 'transform 350ms cubic-bezier(0.4,0,0.2,1)'; el.style.transform = '' })
      setTimeout(() => frames.forEach(({ el }) => { el.style.transition = '' }), 350)
    })
  }, [sorted])

  // Animate checked items sliding in after "Show Completed"
  useLayoutEffect(() => {
    if (!showingRef.current) return
    showingRef.current = false
    const container = containerRef.current
    if (!container) return
    const wrappers = sorted.filter(t => t.checked).map(t =>
      container.querySelector(`[data-swipe-id="${t.id}"]`)?.parentElement
    ).filter(Boolean)
    if (!wrappers.length) return
    wrappers.forEach(el => { el.style.overflow = 'hidden'; el.style.maxHeight = '0'; el.style.opacity = '0'; el.style.transition = 'none' })
    document.body.offsetHeight
    requestAnimationFrame(() => {
      wrappers.forEach(el => { el.style.transition = 'max-height 220ms ease, opacity 180ms ease'; el.style.maxHeight = el.scrollHeight + 'px'; el.style.opacity = '1' })
      setTimeout(() => wrappers.forEach(el => { el.style.maxHeight = ''; el.style.overflow = ''; el.style.transition = ''; el.style.opacity = '' }), 220)
    })
  }, [hideCompleted, sorted])

  // Close the three-dot menu on outside click
  useEffect(() => {
    if (!menuOpen) return
    const handler = (e) => { if (menuRef.current && !menuRef.current.contains(e.target)) setMenuOpen(false) }
    document.addEventListener('pointerdown', handler)
    return () => document.removeEventListener('pointerdown', handler)
  }, [menuOpen])

  // Hide the menu (and close it) when there are no completed items
  useEffect(() => { if (!hasChecked) setMenuOpen(false) }, [hasChecked])

  // Look the open todo up from the full data so it survives being deactivated (and removed from this card's items)
  let openTodo = null, openTodoCat = null, openTodoProj = null
  if (openTodoId != null) {
    for (const cat of categories) {
      for (const p of cat.projects) {
        const t = p.todos.find(x => x.id === openTodoId)
        if (t) { openTodo = t; openTodoCat = cat.id; openTodoProj = p; break }
      }
      if (openTodo) break
    }
  }

  if (items.length === 0 && !openTodo) return null

  const handleCheckboxDown = (e, id) => {
    e.stopPropagation()
    checkPopping.current[id] = false
    const checkboxEl = e.currentTarget.querySelector('.checkbox')
    if (checkboxEl) {
      checkboxEl.getAnimations().forEach(a => a.cancel())
      checkboxEl.animate([{ transform: 'scale(1)' }, { transform: 'scale(0.82)' }], { duration: 100, fill: 'forwards' })
    }
    checkTimers.current[id] = setTimeout(() => {}, 300)
  }

  const handleCheckboxUp = (e, id) => {
    e.stopPropagation()
    clearTimeout(checkTimers.current[id])
    const item = items.find(t => t.id === id)
    if (!item) return
    const checkboxEl = e.currentTarget.querySelector('.checkbox')
    if (!checkboxEl) { onToggle(item.categoryId, item.projectId, id); return }
    const isChecked = item.checked
    checkPopping.current[id] = true
    const popAnim = checkboxEl.animate(
      [{ transform: 'scale(0.82)' }, { transform: 'scale(1.3)' }, { transform: 'scale(1)' }],
      { duration: 350, easing: 'ease', fill: 'forwards' }
    )
    popAnim.onfinish = () => checkboxEl.getAnimations().forEach(a => a.cancel())
    if (!isChecked) {
      checkboxEl.classList.add('checked')
      e.currentTarget.closest('.todo-row')?.classList.add('checked')
      const todoRow = e.currentTarget.closest('.todo-row')
      if (todoRow) {
        const rgb = getComputedStyle(todoRow).getPropertyValue('--accent-base-rgb').trim() || '96,119,135'
        todoRow.animate([{ background: `rgba(${rgb},0)` }, { background: `rgba(${rgb},0.18)`, offset: 0.2 }, { background: `rgba(${rgb},0)` }], { duration: 500, easing: 'ease', fill: 'none' })
      }
      setTimeout(() => {
        if (containerRef.current) toggleFlipRef.current = [...containerRef.current.children].map(el => ({ el, top: el.getBoundingClientRect().top }))
        onToggle(item.categoryId, item.projectId, id)
      }, 500)
    } else {
      if (containerRef.current) toggleFlipRef.current = [...containerRef.current.children].map(el => ({ el, top: el.getBoundingClientRect().top }))
      onToggle(item.categoryId, item.projectId, id)
    }
  }

  const onTodoTap = (e, id) => {
    if (e.target.closest('.swipe-action-btn') || e.target.closest('.checkbox-wrap')) return
    const row = e.currentTarget.closest('.swipe-row')
    if (!row) return
    if (row.classList.contains('swiped-left') || row.classList.contains('swiped-right')) return
    todoTapState.current = { startX: e.clientX, startY: e.clientY, moved: false }
    const onMove = (e2) => {
      const s = todoTapState.current
      if (Math.abs(e2.clientX - s.startX) > 8 || Math.abs(e2.clientY - s.startY) > 8) s.moved = true
    }
    const onUp = () => {
      if (!todoTapState.current.moved) setOpenTodoId(id)
      cleanup()
    }
    const cleanup = () => { document.removeEventListener('pointermove', onMove); document.removeEventListener('pointerup', onUp) }
    document.addEventListener('pointermove', onMove)
    document.addEventListener('pointerup', onUp)
  }

  const handleToggleHideCompleted = () => {
    if (!hideCompleted) {
      const container = containerRef.current
      const wrappers = sorted.filter(t => t.checked).map(t =>
        container?.querySelector(`[data-swipe-id="${t.id}"]`)?.parentElement
      ).filter(Boolean)
      wrappers.forEach(el => {
        el.style.overflow = 'hidden'; el.style.maxHeight = el.getBoundingClientRect().height + 'px'
        el.offsetHeight
        el.style.transition = 'max-height 200ms ease, opacity 150ms ease'; el.style.maxHeight = '0'; el.style.opacity = '0'
      })
      setTimeout(() => {
        wrappers.forEach(el => { el.style.maxHeight = ''; el.style.overflow = ''; el.style.transition = ''; el.style.opacity = '' })
        setHideCompleted(true)
        try { localStorage.setItem('hc-activated-todos', 'true') } catch {}
      }, 210)
    } else {
      showingRef.current = true
      setHideCompleted(false)
      try { localStorage.setItem('hc-activated-todos', 'false') } catch {}
    }
  }

  return (
    <div className="card card-intro" ref={cardRef}>
      <div className="card-header">
        <span className="card-title">Lists</span>
        {hasChecked && (
          <div className="dots-menu-wrap" ref={menuRef}>
            <div
              className="dots-menu dots-menu-btn"
              onMouseDown={e => { e.preventDefault(); setMenuOpen(v => !v) }}
            >
              <span/><span/><span/>
            </div>
              <div className={`card-context-menu${menuOpen ? ' open' : ''}`}>
                <button
                  className="card-context-item"
                  onMouseDown={e => { e.preventDefault(); handleToggleHideCompleted(); setMenuOpen(false) }}
                >
                  {hideCompleted ? `Show ${items.filter(t => t.checked).length} Completed` : 'Hide Completed'}
                </button>
              </div>
          </div>
        )}
      </div>
      <div ref={containerRef}>
        {sorted.map((t, i) => {
          const catIdx = categories.findIndex(c => c.id === t.categoryId)
          const a = catIdx >= 0 ? getCategoryAccent(catIdx) : ACCENT_COLORS[0]
          return (
          <div key={t.id}>
            {i > 0 && <div className="divider"/>}
            <div className={`swipe-row${t.id === openTodoId ? ' row-open' : ''}`} data-swipe-id={t.id} style={{ '--accent-base': a.base, '--accent-light': a.light, '--accent-dark': a.dark, '--accent-base-rgb': a.baseRgb }}>
              <ActivatedSwipeButton id={t.id} onTap={handleDeactivate} onLongPress={openSchedule} />
              <button className="swipe-action-btn delete" onMouseDown={e => { e.preventDefault(); handleDelete(t.id) }}>
                <div className="swipe-active-inner"><TrashSvg/></div>
              </button>
              <div className="swipe-content">
                <div
                  className={`todo-row${t.checked ? ' checked' : ''}`}
                  data-id={t.id}
                  onPointerDown={e => { onPointerDown(e, t.id); onTodoTap(e, t.id); onDragPointerDown(e, t.id) }}
                >
                  <div
                    className="checkbox-wrap"
                    onPointerDown={e => handleCheckboxDown(e, t.id)}
                    onPointerUp={e => handleCheckboxUp(e, t.id)}
                    onPointerLeave={e => {
                      clearTimeout(checkTimers.current[t.id])
                      if (!checkPopping.current[t.id]) {
                        e.currentTarget.querySelector('.checkbox')?.getAnimations().forEach(a => a.cancel())
                      }
                    }}
                  >
                    <div
                      className={`checkbox activated-checkbox${t.checked ? ' checked' : ''}`}
                      style={{ '--cb-base': a.base, '--cb-light': a.light, '--cb-dark': a.dark, '--cb-base-rgb': a.baseRgb }}
                    >
                      <svg className="checkmark" width="16" height="16" viewBox="0 0 12 12" fill="none">
                        <path d="M2 6L5 9L10 3" stroke="white" strokeWidth="1" strokeLinecap="round" strokeLinejoin="round"/>
                      </svg>
                    </div>
                  </div>
                  <div className="item-content">
                    <span className={`item-text${t.checked ? ' checked-text' : ''}`}>{t.text}</span>
                    <div className="source-label">
                      <span className="source-label-text">{t.projectName}</span>
                    </div>
                  </div>
                  {((t.linkedNoteIds?.length || 0) + (t.linkedLinkIds?.length || 0)) > 0 && (
                    <span className="todo-attach-indicator">
                      <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                        <path d="M21 11.5l-8.6 8.6a5 5 0 01-7.07-7.07l8.6-8.6a3.33 3.33 0 014.71 4.71l-8.6 8.6a1.67 1.67 0 01-2.36-2.36l7.9-7.9" stroke="currentColor" strokeWidth="1" strokeLinecap="round" strokeLinejoin="round"/>
                      </svg>
                    </span>
                  )}
                </div>
              </div>
            </div>
          </div>
          )
        })}
      </div>

      {openTodo && createPortal(
        <TodoDetailPage
          todo={openTodo}
          categoryId={openTodoCat}
          projectId={openTodoProj.id}
          projectNotes={openTodoProj.notes || []}
          projectLinks={openTodoProj.links || []}
          onClose={() => setOpenTodoId(null)}
        />,
        document.getElementById('app')
      )}

      {calFor && (
        <CalendarPopup
          anchorRect={calFor.anchorRect}
          initialDate={calFor.current}
          accent={calFor.accent}
          onSelect={(d) => setProjectTodoScheduled(calFor.categoryId, calFor.projectId, calFor.id, d)}
          onClose={() => setCalFor(null)}
        />
      )}
    </div>
  )
}

// Activated notes — aggregated from all projects into one "Notes" card
function ActivatedNotesCard({ items, onDelete, onDeactivate }) {
  const { reorderHomeNotes, updateProjectNote, toggleProjectNoteActivated, categories, setProjectNoteScheduled, openDetail, setOpenDetail } = useAppContext()
  const [calFor, setCalFor] = useState(null)
  const openSchedule = useCallback((id, el) => {
    const item = items.find(t => t.id === id)
    if (!item) return
    closeSwipeRow(el?.closest('.swipe-row'))
    const idx = categories.findIndex(c => c.id === item.categoryId)
    setCalFor({ id, categoryId: item.categoryId, projectId: item.projectId, current: item.scheduledDate || null, anchorRect: toAnchorRect(el), accent: idx >= 0 ? getCategoryAccent(idx) : null })
  }, [items, categories])
  const categoriesRef = useRef(categories)
  categoriesRef.current = categories
  const openNoteId = openDetail?.type === 'note' ? openDetail.id : null
  const setOpenNoteId = (id) => setOpenDetail(id == null ? null : (prev => (prev?.type === 'note' && prev.id === id) ? null : { type: 'note', id }))
  const cardRef = useRef(null)
  const containerRef = useRef(null)
  const noteSwipeState = useRef({})

  const activatedNotes = items

  const handleDelete = useCallback((id) => {
    const item = items.find(n => n.id === id)
    if (!item) return
    const swipeRow = containerRef.current?.querySelector(`[data-swipe-id="${id}"]`)
    const wrapper = swipeRow?.parentElement
    if (!wrapper) { onDelete(item.categoryId, item.projectId, id); return }
    wrapper.animate([{ background: 'rgba(178,74,74,0)' }, { background: 'rgba(178,74,74,0.20)', offset: 0.4 }, { background: 'rgba(178,74,74,0)' }], { duration: 280, fill: 'none' })
    setTimeout(() => {
      const height = wrapper.getBoundingClientRect().height
      wrapper.style.height = height + 'px'; wrapper.style.overflow = 'hidden'
      requestAnimationFrame(() => requestAnimationFrame(() => { wrapper.style.transition = 'height 220ms ease, opacity 180ms ease'; wrapper.style.height = '0'; wrapper.style.opacity = '0' }))
      setTimeout(() => onDelete(item.categoryId, item.projectId, id), 250)
    }, 180)
  }, [onDelete, items])

  const handleDeactivate = useCallback((id) => {
    const item = items.find(n => n.id === id)
    if (!item) return
    const swipeRow = containerRef.current?.querySelector(`[data-swipe-id="${id}"]`)
    const wrapper = swipeRow?.parentElement
    if (!wrapper) { onDeactivate(item.categoryId, item.projectId, id); return }
    const catIdx = categories.findIndex(c => c.id === item.categoryId)
    const a = catIdx >= 0 ? getCategoryAccent(catIdx) : ACCENT_COLORS[0]
    // First close the row (snap back to center)
    closeSwipeRow(swipeRow)
    setTimeout(() => {
      // Then flash and collapse
      wrapper.animate([{ background: `rgba(${a.baseRgb},0)` }, { background: `rgba(${a.baseRgb},0.25)`, offset: 0.4 }, { background: `rgba(${a.baseRgb},0)` }], { duration: 280, fill: 'none' })
      setTimeout(() => {
        const height = wrapper.getBoundingClientRect().height
        wrapper.style.height = height + 'px'; wrapper.style.overflow = 'hidden'
        requestAnimationFrame(() => requestAnimationFrame(() => { wrapper.style.transition = 'height 220ms ease, opacity 180ms ease'; wrapper.style.height = '0'; wrapper.style.opacity = '0' }))
        setTimeout(() => onDeactivate(item.categoryId, item.projectId, id), 250)
      }, 180)
    }, 200)
  }, [onDeactivate, items, categories])

  const handleReorder = useCallback((newOrder) => {
    // Single cross-project order for the home Notes card.
    reorderHomeNotes(newOrder)
  }, [reorderHomeNotes])

  const handleNoteSave = useCallback((noteId, html, text) => {
    const item = items.find(n => n.id === noteId)
    if (!item) return
    updateProjectNote(item.categoryId, item.projectId, noteId, html, text)
  }, [updateProjectNote, items])

  const { onDragPointerDown } = useDragReorder(containerRef, activatedNotes, handleReorder)

  const onNotePointerDown = useCallback((e, id) => {
    if (e.target.closest('.swipe-action-btn')) return
    const row = e.currentTarget  // handler is on .swipe-row, so this IS the row
    if (!row) return

    // If a button is exposed, close and swallow — note must not open
    if (row.classList.contains('swiped-left') || row.classList.contains('swiped-right')) {
      row.classList.remove('swiped-left', 'swiped-right')
      const content = row.querySelector('.swipe-content')
      if (content) content.style.transform = ''
      return
    }

    const wasLeft = false
    const wasRight = false
    noteSwipeState.current = { id, startX: e.clientX, startY: e.clientY, row, dir: null, wasLeft, wasRight, lockSign: null }

    const onMove = (e2) => {
      const s = noteSwipeState.current
      if (!s.row) return
      const dx = e2.clientX - s.startX, dy = e2.clientY - s.startY
      if (!s.dir) {
        if (Math.abs(dy) > 8) { cleanup(); return }
        if (Math.abs(dx) > 10) s.dir = dx < 0 ? 'left' : 'right'
        else return
      }
      const content = s.row.querySelector('.swipe-content')
      if (!content) return
      const base = s.wasLeft ? -84 : s.wasRight ? 84 : 0
      const proposed = base + dx
      if (s.lockSign === null && Math.abs(proposed) > 2) s.lockSign = proposed > 0 ? 1 : -1
      let newX = Math.max(-84, Math.min(84, proposed))
      if (s.lockSign === 1 || s.wasRight) newX = Math.max(0, newX)
      if (s.lockSign === -1 || s.wasLeft) newX = Math.min(0, newX)
      content.style.transition = 'none'
      content.style.transform = `translateX(${newX}px)`
    }

    const onUp = (e2) => {
      const s = noteSwipeState.current
      if (!s.row) { cleanup(); return }
      const dx = e2.clientX - s.startX
      const dy = e2.clientY - s.startY
      const content = s.row.querySelector('.swipe-content')
      if (!content) { cleanup(); return }
      content.style.transition = ''
      const isTap = !s.dir && Math.abs(dx) < 8 && Math.abs(dy) < 8
      if (isTap) {
        setOpenNoteId(id)
        cleanup()
        return
      }
      const base = s.wasLeft ? -84 : s.wasRight ? 84 : 0
      const rawTotal = base + dx
      let total = s.wasRight ? Math.max(0, rawTotal) : s.wasLeft ? Math.min(0, rawTotal) : rawTotal
      if (s.lockSign === 1) total = Math.max(0, total)
      if (s.lockSign === -1) total = Math.min(0, total)
      if (total < -36) { s.row.classList.add('swiped-left'); s.row.classList.remove('swiped-right'); content.style.transform = '' }
      else if (total > 36) { s.row.classList.add('swiped-right'); s.row.classList.remove('swiped-left'); content.style.transform = '' }
      else { s.row.classList.remove('swiped-left', 'swiped-right'); content.style.transform = '' }
      cleanup()
    }

    const handleCancel = () => {
      const s2 = noteSwipeState.current
      if (s2.row && s2.dir) {
        // Only settle the row if actual dragging occurred — not on a plain tap
        const c2 = s2.row.querySelector('.swipe-content')
        if (c2) {
          c2.style.transition = ''
          const m = c2.style.transform.match(/translateX\((-?[\d.]+)px\)/)
          const cx = m ? parseFloat(m[1]) : 0
          if (cx < -36) { s2.row.classList.add('swiped-left'); s2.row.classList.remove('swiped-right') }
          else if (cx > 36) { s2.row.classList.add('swiped-right'); s2.row.classList.remove('swiped-left') }
          else { s2.row.classList.remove('swiped-left', 'swiped-right') }
          c2.style.transform = ''
        }
      }
      document.removeEventListener('pointermove', onMove)
      document.removeEventListener('pointerup', onUp)
      document.removeEventListener('pointercancel', handleCancel)
    }

    const cleanup = () => {
      document.removeEventListener('pointermove', onMove)
      document.removeEventListener('pointerup', onUp)
      document.removeEventListener('pointercancel', handleCancel)
    }

    document.addEventListener('pointermove', onMove)
    document.addEventListener('pointerup', onUp)
    document.addEventListener('pointercancel', handleCancel)
  }, [])

  useEffect(() => {
    const card = cardRef.current
    if (!card) return
    requestAnimationFrame(() => card.classList.add('visible'))
  }, [])

  // Look the open note up from the full data so it survives being deactivated (and removed from this card's items)
  let openNote = null
  if (openNoteId != null) {
    outer:
    for (const cat of categories) {
      for (const p of cat.projects) {
        const n = p.notes.find(x => x.id === openNoteId)
        if (n) { openNote = { ...n, categoryId: cat.id, projectId: p.id, projectName: p.name }; break outer }
      }
    }
  }

  if (activatedNotes.length === 0 && !openNote) return null

  return (
    <>
      <div className="card card-intro" ref={cardRef}>
        <div className="card-header">
          <span className="card-title">Notes</span>
        </div>
        <div ref={containerRef}>
          {activatedNotes.map((n, i) => {
            const catIdx = categories.findIndex(c => c.id === n.categoryId)
            const a = catIdx >= 0 ? getCategoryAccent(catIdx) : ACCENT_COLORS[0]
            return (
            <div key={n.id}>
              {i > 0 && <div className="divider"/>}
              <div className={`swipe-row${n.id === openNoteId ? ' row-open' : ''}`} data-swipe-id={n.id} style={{ '--accent-base': a.base, '--accent-light': a.light, '--accent-dark': a.dark, '--accent-base-rgb': a.baseRgb }} onPointerDown={e => { onNotePointerDown(e, n.id); onDragPointerDown(e, n.id) }}>
                <ActivatedSwipeButton id={n.id} onTap={handleDeactivate} onLongPress={openSchedule} />
                <button className="swipe-action-btn delete" onMouseDown={e => { e.preventDefault(); handleDelete(n.id) }}>
                  <div className="swipe-active-inner"><TrashSvg/></div>
                </button>
                <div className="swipe-content">
                  <div className="note-row" data-note-id={n.id}>
                    <div className="checkbox-wrap" style={{ pointerEvents: 'none' }}>
                      <svg width="24" height="24" viewBox="0 0 20 22" fill="none">
                        <path d="M3 3h9l5 5v12a1 1 0 01-1 1H3a1 1 0 01-1-1V4a1 1 0 011-1z" stroke={a.dark} strokeWidth="1" fill={a.light}/>
                        <path d="M12 3v5h5" stroke={a.dark} strokeWidth="1" fill="none"/>
                        <line x1="5" y1="13" x2="15" y2="13" stroke={a.dark} strokeWidth="1" strokeLinecap="round"/>
                        <line x1="5" y1="16.5" x2="12" y2="16.5" stroke={a.dark} strokeWidth="1" strokeLinecap="round"/>
                      </svg>
                    </div>
                    <div className="item-content">
                      <span className="note-text">{n.text}</span>
                      <div className="source-label">
                        <span className="source-label-text">{n.projectName}</span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
            )
          })}
        </div>
      </div>
      {openNote && createPortal(
        <NoteDetailPage
          note={openNote}
          onClose={() => setOpenNoteId(null)}
          onSave={handleNoteSave}
          activated={!!openNote.activated}
          onToggleActive={() => toggleProjectNoteActivated(openNote.categoryId, openNote.projectId, openNote.id)}
          projectName={openNote.projectName}
          categoryId={openNote.categoryId}
          projectId={openNote.projectId}
        />,
        document.getElementById('app')
      )}

      {calFor && (
        <CalendarPopup
          anchorRect={calFor.anchorRect}
          initialDate={calFor.current}
          accent={calFor.accent}
          onSelect={(d) => setProjectNoteScheduled(calFor.categoryId, calFor.projectId, calFor.id, d)}
          onClose={() => setCalFor(null)}
        />
      )}
    </>
  )
}

// Activated links — aggregated from all projects into one "Links" card
function ActivatedLinksCard({ items, onDelete, onDeactivate }) {
  const { categories, setProjectLinkScheduled, reorderHomeLinks } = useAppContext()
  const categoriesRef = useRef(categories)
  categoriesRef.current = categories
  const [calFor, setCalFor] = useState(null)
  const openSchedule = useCallback((id, el) => {
    const item = items.find(t => t.id === id)
    if (!item) return
    closeSwipeRow(el?.closest('.swipe-row'))
    const idx = categories.findIndex(c => c.id === item.categoryId)
    setCalFor({ id, categoryId: item.categoryId, projectId: item.projectId, current: item.scheduledDate || null, anchorRect: toAnchorRect(el), accent: idx >= 0 ? getCategoryAccent(idx) : null })
  }, [items, categories])
  const cardRef = useRef(null)
  const containerRef = useRef(null)
  const linkSwipeState = useRef({})

  const handleDelete = useCallback((id) => {
    const item = items.find(l => l.id === id)
    if (!item) return
    const swipeRow = containerRef.current?.querySelector(`[data-swipe-id="${id}"]`)
    const wrapper = swipeRow?.parentElement
    if (!wrapper) { onDelete(item.categoryId, item.projectId, id); return }
    wrapper.animate([{ background: 'rgba(178,74,74,0)' }, { background: 'rgba(178,74,74,0.20)', offset: 0.4 }, { background: 'rgba(178,74,74,0)' }], { duration: 280, fill: 'none' })
    setTimeout(() => {
      const height = wrapper.getBoundingClientRect().height
      wrapper.style.height = height + 'px'; wrapper.style.overflow = 'hidden'
      requestAnimationFrame(() => requestAnimationFrame(() => { wrapper.style.transition = 'height 220ms ease, opacity 180ms ease'; wrapper.style.height = '0'; wrapper.style.opacity = '0' }))
      setTimeout(() => onDelete(item.categoryId, item.projectId, id), 250)
    }, 180)
  }, [onDelete, items])

  const handleDeactivate = useCallback((id) => {
    const item = items.find(l => l.id === id)
    if (!item) return
    const swipeRow = containerRef.current?.querySelector(`[data-swipe-id="${id}"]`)
    const wrapper = swipeRow?.parentElement
    if (!wrapper) { onDeactivate(item.categoryId, item.projectId, id); return }
    const catIdx = categories.findIndex(c => c.id === item.categoryId)
    const a = catIdx >= 0 ? getCategoryAccent(catIdx) : ACCENT_COLORS[0]
    closeSwipeRow(swipeRow)
    setTimeout(() => {
      wrapper.animate([{ background: `rgba(${a.baseRgb},0)` }, { background: `rgba(${a.baseRgb},0.25)`, offset: 0.4 }, { background: `rgba(${a.baseRgb},0)` }], { duration: 280, fill: 'none' })
      setTimeout(() => {
        const height = wrapper.getBoundingClientRect().height
        wrapper.style.height = height + 'px'; wrapper.style.overflow = 'hidden'
        requestAnimationFrame(() => requestAnimationFrame(() => { wrapper.style.transition = 'height 220ms ease, opacity 180ms ease'; wrapper.style.height = '0'; wrapper.style.opacity = '0' }))
        setTimeout(() => onDeactivate(item.categoryId, item.projectId, id), 250)
      }, 180)
    }, 200)
  }, [onDeactivate, items, categories])

  const handleReorder = useCallback((newOrder) => {
    // Single cross-project order for the home Links card.
    reorderHomeLinks(newOrder)
  }, [reorderHomeLinks])

  const { onDragPointerDown } = useDragReorder(containerRef, items, handleReorder)

  const onLinkPointerDown = useCallback((e, id, url) => {
    if (e.target.closest('.swipe-action-btn')) return
    const row = e.currentTarget
    if (!row) return
    if (row.classList.contains('swiped-left') || row.classList.contains('swiped-right')) {
      row.classList.remove('swiped-left', 'swiped-right')
      const content = row.querySelector('.swipe-content')
      if (content) content.style.transform = ''
      return
    }
    linkSwipeState.current = { id, startX: e.clientX, startY: e.clientY, row, dir: null, lockSign: null }

    const onMove = (e2) => {
      const s = linkSwipeState.current
      if (!s.row) return
      const dx = e2.clientX - s.startX, dy = e2.clientY - s.startY
      if (!s.dir) {
        if (Math.abs(dy) > 8) { cleanup(); return }
        if (Math.abs(dx) > 10) s.dir = dx < 0 ? 'left' : 'right'
        else return
      }
      const content = s.row.querySelector('.swipe-content')
      if (!content) return
      const proposed = dx
      if (s.lockSign === null && Math.abs(proposed) > 2) s.lockSign = proposed > 0 ? 1 : -1
      let newX = Math.max(-84, Math.min(84, proposed))
      if (s.lockSign === 1) newX = Math.max(0, newX)
      if (s.lockSign === -1) newX = Math.min(0, newX)
      content.style.transition = 'none'
      content.style.transform = `translateX(${newX}px)`
    }

    const onUp = (e2) => {
      const s = linkSwipeState.current
      if (!s.row) { cleanup(); return }
      const dx = e2.clientX - s.startX
      const dy = e2.clientY - s.startY
      const content = s.row.querySelector('.swipe-content')
      if (!content) { cleanup(); return }
      content.style.transition = ''
      const isTap = !s.dir && Math.abs(dx) < 8 && Math.abs(dy) < 8
      if (isTap) { openUrl(url); cleanup(); return }
      let total = dx
      if (s.lockSign === 1) total = Math.max(0, total)
      if (s.lockSign === -1) total = Math.min(0, total)
      if (total < -36) { s.row.classList.add('swiped-left'); s.row.classList.remove('swiped-right'); content.style.transform = '' }
      else if (total > 36) { s.row.classList.add('swiped-right'); s.row.classList.remove('swiped-left'); content.style.transform = '' }
      else { s.row.classList.remove('swiped-left', 'swiped-right'); content.style.transform = '' }
      cleanup()
    }

    const cleanup = () => {
      document.removeEventListener('pointermove', onMove)
      document.removeEventListener('pointerup', onUp)
    }
    document.addEventListener('pointermove', onMove)
    document.addEventListener('pointerup', onUp)
  }, [])

  useEffect(() => {
    const card = cardRef.current
    if (!card) return
    requestAnimationFrame(() => card.classList.add('visible'))
  }, [])

  if (items.length === 0) return null

  return (
    <div className="card card-intro" ref={cardRef}>
      <div className="card-header">
        <span className="card-title">Links</span>
      </div>
      <div ref={containerRef}>
        {items.map((l, i) => {
          const catIdx = categories.findIndex(c => c.id === l.categoryId)
          const a = catIdx >= 0 ? getCategoryAccent(catIdx) : ACCENT_COLORS[0]
          return (
          <div key={l.id}>
            {i > 0 && <div className="divider"/>}
            <div className="swipe-row" data-swipe-id={l.id} style={{ '--accent-base': a.base, '--accent-light': a.light, '--accent-dark': a.dark, '--accent-base-rgb': a.baseRgb }} onPointerDown={e => { onLinkPointerDown(e, l.id, l.url); onDragPointerDown(e, l.id) }}>
              <ActivatedSwipeButton id={l.id} onTap={handleDeactivate} onLongPress={openSchedule} />
              <button className="swipe-action-btn delete" onMouseDown={e => { e.preventDefault(); handleDelete(l.id) }}>
                <div className="swipe-active-inner"><TrashSvg/></div>
              </button>
              <div className="swipe-content">
                <div className="note-row">
                  <div className="checkbox-wrap" style={{ pointerEvents: 'none' }}>
                    <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                      <circle cx="12" cy="12" r="8" fill={a.light}/>
                      <path d="M10 13a5 5 0 007.54.54l3-3a5 5 0 00-7.07-7.07l-1.72 1.71" stroke={a.dark} strokeWidth="1" strokeLinecap="round" strokeLinejoin="round"/>
                      <path d="M14 11a5 5 0 00-7.54-.54l-3 3a5 5 0 007.07 7.07l1.71-1.71" stroke={a.dark} strokeWidth="1" strokeLinecap="round" strokeLinejoin="round"/>
                    </svg>
                  </div>
                  <div className="item-content">
                    <span className="note-text">{l.title}</span>
                    <div className="source-label">
                      <span className="source-label-text">{l.projectName}</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
          )
        })}
      </div>

      {calFor && (
        <CalendarPopup
          anchorRect={calFor.anchorRect}
          initialDate={calFor.current}
          accent={calFor.accent}
          onSelect={(d) => setProjectLinkScheduled(calFor.categoryId, calFor.projectId, calFor.id, d)}
          onClose={() => setCalFor(null)}
        />
      )}
    </div>
  )
}

export default function ActivePage({
  todos, notes,
  onToggleTodo, onDeleteTodo, onDeleteNote, onUpdateNote,
  onReorderTodos, onReorderNotes,
  onScroll, headerOpacity, headerTranslate,
  pageAnimClass = '', isExiting = false,
}) {
  const pageRef = useRef(null)
  const { categories, toggleProjectTodo, deleteProjectTodo, deleteProjectNote, deleteProjectLink, toggleProjectTodoActivated, toggleProjectNoteActivated, toggleProjectLinkActivated } = useAppContext()

  // Fade a drop shadow in behind the cards over the first 56px of scrolling (0% → 4%)
  const handleScroll = useCallback((e) => {
    if (onScroll) onScroll(e)
    const y = e.target.scrollTop
    const opacity = Math.min(0.06, Math.max(0, (y / 56) * 0.06))
    if (pageRef.current) pageRef.current.style.setProperty('--card-scroll-shadow', String(opacity))
  }, [onScroll])

  const [underlineColorIdx, setUnderlineColorIdx] = useState(0)
  useEffect(() => {
    const id = setInterval(() => {
      setUnderlineColorIdx(i => (i + 1) % ACCENT_COLORS.length)
    }, 3000)
    return () => clearInterval(id)
  }, [])

  const now = new Date()
  const dayName = now.toLocaleDateString('en-US', { weekday: 'long' })
  const monthDate = now.toLocaleDateString('en-US', { month: 'long', day: 'numeric' })

  // Collect all activated items across all categories/projects as flat tagged arrays.
  // Categories with sendToHomescreen === false keep their active items off the homescreen.
  const homescreenCats = categories.filter(cat => cat.sendToHomescreen !== false)
  // Stable sort by the cross-project home order. Items without a value (freshly
  // activated, never manually ordered) fall back to the aggregation order (end).
  const byHomeOrder = (a, b) => (a.homeSortOrder ?? Infinity) - (b.homeSortOrder ?? Infinity)
  const allActivatedTodos = homescreenCats.flatMap(cat =>
    cat.projects.flatMap(proj =>
      proj.todos.filter(t => t.activated).map(t => ({ ...t, categoryId: cat.id, projectId: proj.id, projectName: proj.name }))
    )
  ).sort(byHomeOrder)
  const allActivatedNotes = homescreenCats.flatMap(cat =>
    cat.projects.flatMap(proj =>
      proj.notes.filter(n => n.activated).map(n => ({ ...n, categoryId: cat.id, projectId: proj.id, projectName: proj.name }))
    )
  ).sort(byHomeOrder)
  const allActivatedLinks = homescreenCats.flatMap(cat =>
    cat.projects.flatMap(proj =>
      proj.links.filter(l => l.activated).map(l => ({ ...l, categoryId: cat.id, projectId: proj.id, projectName: proj.name }))
    )
  ).sort(byHomeOrder)

  // Decoration colour = base colour of the category contributing the most items to the Lists card
  const listCatCounts = {}
  ;[...allActivatedTodos, ...todos].forEach(t => {
    if (t.categoryId) listCatCounts[t.categoryId] = (listCatCounts[t.categoryId] || 0) + 1
  })
  let domCatId = null, domCatMax = 0
  for (const cid in listCatCounts) {
    if (listCatCounts[cid] > domCatMax) { domCatMax = listCatCounts[cid]; domCatId = cid }
  }
  const domCatIdx = domCatId ? categories.findIndex(c => c.id === domCatId) : -1
  const decorationColor = domCatIdx >= 0 ? getCategoryAccent(domCatIdx).base : ACCENT_COLORS[0].base

  const hasContent = todos.length > 0 || notes.length > 0 || allActivatedTodos.length > 0 || allActivatedNotes.length > 0 || allActivatedLinks.length > 0

  return (
    <div className={`page active${pageAnimClass ? ` ${pageAnimClass}` : ''}`} id={isExiting ? undefined : 'page-star'} ref={pageRef} onScroll={handleScroll}>
      <div className="page-header" style={{ opacity: headerOpacity, transform: `translateY(${headerTranslate}px)` }}>
        <p className="active-today-label">Today is</p>
        <p className="active-day-name">{dayName},</p>
        <GalleryDecoration className="active-date-decoration" style={{ color: decorationColor }} />
        <p className="active-month-date">{monthDate}</p>
      </div>

      {!hasContent && (
        <div className="empty-state" id="emptyState">
          <p>Scribble something down to get started!</p>
        </div>
      )}

      <div className="cards-area" id="cardsArea">
        <TodoCard
          todos={todos}
          onToggle={onToggleTodo}
          onDelete={onDeleteTodo}
          onReorder={onReorderTodos}
        />
        <NoteCard
          notes={notes}
          onDelete={onDeleteNote}
          onUpdateNote={onUpdateNote}
          onReorder={onReorderNotes}
        />
        {allActivatedTodos.length > 0 && (
          <ActivatedTodosCard
            items={allActivatedTodos}
            onToggle={toggleProjectTodo}
            onDelete={deleteProjectTodo}
            onDeactivate={toggleProjectTodoActivated}
          />
        )}
        {allActivatedNotes.length > 0 && (
          <ActivatedNotesCard
            items={allActivatedNotes}
            onDelete={deleteProjectNote}
            onDeactivate={toggleProjectNoteActivated}
          />
        )}
        {allActivatedLinks.length > 0 && (
          <ActivatedLinksCard
            items={allActivatedLinks}
            onDelete={deleteProjectLink}
            onDeactivate={toggleProjectLinkActivated}
          />
        )}
      </div>
    </div>
  )
}
